import auth from './auth.services.js';
import { Router } from 'express';
import { signUpSchema, signInSchema, resetPassword, confirmLoginSchema, } from './auth.validationSchema.js';
import { validationMiddleWare } from '../../common/middleware/validation.js';
export const authRouter = Router();
authRouter.post('/sign-up', validationMiddleWare(signUpSchema), auth.signUp);
authRouter.post('/log-in', validationMiddleWare(signInSchema), auth.logIn);
authRouter.post('/confirm-mail', auth.confirmMail);
authRouter.post('/confirm-login-in', validationMiddleWare(confirmLoginSchema), auth.confirmLogin);
authRouter.get('/resend-otp', auth.reSendOtp);
authRouter.post('/sign-with-google', auth.signUpAndLoginWithGmail);
authRouter.patch('/reset-password', validationMiddleWare(resetPassword), auth.resetPassword);
authRouter.get('/access-token', validationMiddleWare(resetPassword), auth.generateAccessToken);
authRouter.get('/refresh-token', auth.generateAccessToken);
